import { stdout } from std.io;
record Point { x: Int32; y: Int32; }
enum Shape {
    Circle(r: Int32),
    Square(s: Int32)
}
class Holder {
    p: Point;
    construct(p: Point) { this.p = p; }
}
fn area(s: Shape): Int32 {
    return match s {
        Shape.Circle(r) => r * r * 3,
        Shape.Square(w) => w * w
    };
}
fn main(): Void {
    inmut h = Holder(Point(x: 1, y: 2));
    stdout.println(h.p.x + h.p.y);
    stdout.println(area(Shape.Circle(2)));
    stdout.println(area(Shape.Square(3)));
    stdout.println(Point(x: 1, y: 2) == Point(x: 1, y: 2));
}
